#!/usr/bin/env bash
# japan-project-rules installer
# Usage: ./install.sh <path-to-project> --config <project.json> [--dry-run] [--no-skills]
# Copies the local-only rule set (and tools/) into a project checkout, hides it from git via
# .git/info/exclude (never .gitignore), installs Cursor skills, and checks tools.
# Every project-specific value (detection, local-only list, executables, env checks) comes from --config
# (generated by ./init.sh). No config / the repo example (_example) / missing keys -> error, no defaults.
set -euo pipefail

KIT_DIR="$(cd "$(dirname "$0")" && pwd)"
PAYLOAD="$KIT_DIR/payload"
DRY=0; SKILLS=1; TARGET=""; CONFIG=""
while [ $# -gt 0 ]; do
  case "$1" in
    --dry-run) DRY=1 ;;
    --no-skills) SKILLS=0 ;;
    --config) shift; CONFIG="${1:-}" ;;
    --config=*) CONFIG="${1#--config=}" ;;
    -h|--help) sed -n '2,7p' "$0"; exit 0 ;;
    *) TARGET="$1" ;;
  esac
  shift
done

red()   { printf '\033[31m%s\033[0m\n' "$*"; }
green() { printf '\033[32m%s\033[0m\n' "$*"; }
yellow(){ printf '\033[33m%s\033[0m\n' "$*"; }
run()   { if [ "$DRY" = 1 ]; then echo "  [dry-run] $*"; else "$@"; fi; }

[ -n "$TARGET" ] || { red "Usage: ./install.sh <path-to-project> --config <project.json> [--dry-run] [--no-skills]"; exit 1; }
[ -n "$CONFIG" ] || { red "ERROR: --config <project.json> is required (generate it with ./init.sh; the example under projects/ is refused)"; exit 2; }
command -v python3 >/dev/null || { red "ERROR: python3 is required to read the project config"; exit 2; }
PC="$KIT_DIR/tools/project_config.py"
python3 "$PC" "$CONFIG" check --tool all >/dev/null || exit 2
cfg()      { python3 "$PC" "$CONFIG" get "$1"; }
cfg_lines(){ python3 "$PC" "$CONFIG" get "$1" --lines; }
TARGET="$(cd "$TARGET" && pwd)"
[ -d "$TARGET/.git" ] || { red "Not a git checkout: $TARGET"; exit 1; }
PROJ="$(cfg name)"
DET_FILE="$(cfg detect.file)"; DET_STR="$(cfg detect.contains)"
if [ -f "$TARGET/$DET_FILE" ] && { [ -z "$DET_STR" ] || grep -qF -- "$DET_STR" "$TARGET/$DET_FILE"; }; then
  echo "Project: $PROJ (detected: $DET_FILE${DET_STR:+ contains '$DET_STR'})"
else
  yellow "Warning: $TARGET does not look like project '$PROJ' ($DET_FILE${DET_STR:+ containing '$DET_STR'} not found). Continuing."
fi

TS="$(date +%Y%m%d_%H%M%S)"
BACKUP="$TARGET/.rules-backup/$TS"
echo "Target : $TARGET"
[ "$DRY" = 1 ] && yellow "Dry run: nothing will be changed."

# 1. Copy payload (back up files that differ)
echo; echo "== 1/4 Copy rules"
copied=0; backed=0
while IFS= read -r -d '' src; do
  case "$src" in
    "$KIT_DIR/tools/"*) rel="${src#$KIT_DIR/}" ;;
    *) rel="${src#$PAYLOAD/}" ;;
  esac
  dst="$TARGET/$rel"
  if [ -f "$dst" ] && cmp -s "$src" "$dst"; then continue; fi
  if [ -f "$dst" ]; then
    run mkdir -p "$(dirname "$BACKUP/$rel")"
    run cp -p "$dst" "$BACKUP/$rel"
    backed=$((backed+1))
  fi
  run mkdir -p "$(dirname "$dst")"
  run cp -p "$src" "$dst"
  copied=$((copied+1))
done < <(find "$PAYLOAD" "$KIT_DIR/tools" -type f ! -name '.DS_Store' ! -name '*.pyc' ! -path '*/__pycache__/*' -print0)
while IFS= read -r x; do
  [ -n "$x" ] || continue
  if [ -e "$TARGET/$x" ] || [ "$DRY" = 1 ]; then run chmod +x "$TARGET/$x"; else yellow "  executable listed in config but missing: $x"; fi
done < <(cfg_lines executable)
green "  copied/updated: $copied file(s); backed up: $backed (→ ${BACKUP#$TARGET/})"

# 2. Hide from git (local only)
echo; echo "== 2/4 Hide rule files from git (.git/info/exclude)"
EXCL="$TARGET/.git/info/exclude"
BEGIN="# >>> japan-project-rules (local only, do not commit) >>>"
END="# <<< japan-project-rules <<<"
# local_only from the config + everything this kit puts under tools/ + the backup dir
ENTRIES="$( { cfg_lines local_only | sed -e 's#^/*#/#'
             for t in "$KIT_DIR"/tools/*; do n="$(basename "$t")"; [ "$n" = __pycache__ ] && continue
               [ -d "$t" ] && echo "/tools/$n/" || echo "/tools/$n"; done
             echo "/.rules-backup/"; } | awk 'NF && !seen[$0]++')"
if [ "$DRY" = 1 ]; then
  echo "  [dry-run] write block to $EXCL"
else
  mkdir -p "$(dirname "$EXCL")"; touch "$EXCL"
  tmp="$(mktemp)"
  awk -v b="$BEGIN" -v e="$END" '$0==b{skip=1} !skip{print} $0==e{skip=0}' "$EXCL" > "$tmp"
  { cat "$tmp"; echo "$BEGIN"; echo "$ENTRIES"; echo "$END"; } > "$EXCL"
  rm -f "$tmp"
fi
LOCAL_PATHS=()
while IFS= read -r x; do x="${x#/}"; x="${x%/}"; [ -n "$x" ] && LOCAL_PATHS+=("$x"); done < <(cfg_lines local_only)
tracked="$(cd "$TARGET" && git ls-files -- "${LOCAL_PATHS[@]}" | head -5)"
if [ -n "$tracked" ]; then
  red "  Some rule files are TRACKED by git in this checkout (exclude does not hide them):"
  echo "$tracked" | sed 's/^/    /'
else
  green "  rule files are untracked and now hidden from git status"
fi

# 3. Skills
echo; echo "== 3/4 Install Cursor skills (~/.cursor/skills)"
if [ "$SKILLS" = 1 ]; then
  for s in "$KIT_DIR"/skills/*/; do
    name="$(basename "$s")"; dst="$HOME/.cursor/skills/$name"
    if [ -d "$dst" ] && diff -rq "$s" "$dst" >/dev/null 2>&1; then
      echo "  $name: up to date"; continue
    fi
    if [ -d "$dst" ]; then run mv "$dst" "$dst.bak.$TS"; echo "  $name: old version → $name.bak.$TS"; fi
    run mkdir -p "$HOME/.cursor/skills"
    run cp -R "$s" "$dst"
    green "  $name: installed"
  done
else
  echo "  skipped (--no-skills)"
fi

# 4. Environment check
echo; echo "== 4/4 Environment check"
ok=1
# env_checks from the config: run each cmd in the project, expect substring in its output ("" = just must succeed)
while IFS=$'\t' read -r name cmd expect; do
  [ -n "$name" ] || continue
  if out="$(cd "$TARGET" && bash -c "$cmd" 2>&1)" && { [ -z "$expect" ] || printf '%s' "$out" | grep -qF -- "$expect"; }; then
    green "  $name: OK ($cmd${expect:+ → contains '$expect'})"
  else
    red "  $name: FAILED ($cmd${expect:+; expected output containing '$expect'}): $(printf '%s' "$out" | head -1)"; ok=0
  fi
done < <(python3 -c 'import json,sys
for c in json.load(open(sys.argv[1], encoding="utf-8"))["env_checks"]:
    print("\t".join([c["name"], c["cmd"], c.get("expect", "")]))' "$CONFIG")
command -v python3 >/dev/null && green "  python3: OK (Chinese-comment hook)" || { red "  python3 not found (needed by .cursor/hooks)"; ok=0; }
if command -v python3 >/dev/null; then
  if python3 -c 'import openpyxl' 2>/dev/null; then green "  openpyxl: OK (tools/*-xlsx)"; else yellow "  openpyxl missing: python3 -m pip install openpyxl  (needed by tools/design-xlsx, tools/unit-test-xlsx)"; fi
  if python3 -c 'import PIL' 2>/dev/null; then green "  Pillow: OK"; else yellow "  Pillow missing: python3 -m pip install pillow  (only when a 画面設計書 contains images)"; fi
fi
echo
[ "$ok" = 1 ] && green "Done." || yellow "Done with warnings (see above)."
cat <<MSG

Next:
  - Open $TARGET in Cursor; rules under .cursor/rules apply automatically.
  - Tools need the same config: python3 tools/design-xlsx/gen_design_xlsx.py ... --config $CONFIG
  - Optional MCP: cp .cursor/mcp.json.example .cursor/mcp.json and fill a READ-ONLY account.
  - Optional e2e: cd e2e && npm install && npx playwright install chromium
  - Never commit the rule files (they are client-invisible by design).
MSG
